insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('11c71b51-0d39-47d4-b733-2c11ea3df4ab', 'es', '¿Qué hace que un coqueteo salga bien?', '["Conseguir su número", "Generar atracción rápido", "Demostrar seguridad", "Crear un momento agradable y lleno de energía"]'::jsonb, 'El coqueteo sale bien cuando el momento se siente más ligero y más vivo, sea cual sea el resultado.')
