insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2016c8a-bb00-46b1-8a8d-c78bcb62decf', 'es', '¿Por qué centrarte en el resultado suele salir mal al coquetear?', '["Acorta las conversaciones", "Frena el avance", "Te quita seguridad", "Crea presión y una intención oculta"]'::jsonb, 'Céntrate en que la interacción sea juguetona en lugar de intentar conseguir un resultado concreto.')
