insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37bff0df-2454-418b-b50a-db2845245a4e', 'es', '¿Por qué centrarte en disfrutar mejora los resultados al coquetear?', '["Elimina las intenciones ocultas", "Te hace estar más presente y relajado", "Hace que no dependas del resultado", "Prioriza demostrar lo que vales"]'::jsonb, 'Disfrutar redefine el éxito como el momento en sí, no como el resultado.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90e66462-8fdd-4fa4-a574-bda55becad8c', 'es', '¿Cómo sabes si debes seguir coqueteando?', '["Confiar en tu intuición sobre la vibra de la interacción", "Fijarte en cómo responde ella, no en cómo te sientes tú", "Esperar a que diga claramente con palabras que le interesas", "Valorar si la conversación ya duró lo suficiente"]'::jsonb, 'Fíjate en sus respuestas y en cuánto se implica, no en cómo te sientes tú.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eee49a49-b918-4f25-9827-edc1a9f9bdc0', 'es', '¿Qué señales sugieren que te contengas en lugar de avanzar?', '["Un tono neutro", "Respuestas cortas", "No te devuelve preguntas", "Una risa genuina"]'::jsonb, 'Si no te devuelve la energía, la interacción todavía no se ha abierto.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ae2493f-bf71-457d-8f09-996e6cf2b464', 'es', '¿Qué significa el respeto al coquetear?', '["Valorar su comodidad y sus límites por encima de tu resultado", "Mostrar seguridad durante toda la interacción", "Tratarla como a una igual sin ser demasiado agresivo"]'::jsonb, 'El coqueteo se mantiene respetuoso cuando valoras su comodidad más que tu éxito.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df3d8e11-15af-468e-ba4a-9cca550456d2', 'es', '¿Cuál es la forma más limpia de proteger a los dos cuando el interés no es mutuo?', '["Despedirte pronto y con educación", "Bromear para suavizar el momento", "Insistir un poco para confirmarlo", "Esperar a que ella te diga que no directamente"]'::jsonb, 'Despedirte pronto y con respeto mantiene el momento ligero y evita la incomodidad para los dos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fed7fe50-0325-493e-8647-62755e05fab5', 'es', '¿Cuáles son los comportamientos mínimos de respeto?', '["Leer sus señales y respetarlas", "Aceptar el rechazo sin hacerla sentir culpable y sin mala actitud", "Nunca tocarla sin señales claras de que está cómoda", "Intentarlo una vez más si crees que puede ser tímida"]'::jsonb, 'El coqueteo se mantiene respetuoso cuando valoras su comodidad más que tu éxito.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('999e00ac-a18d-4b94-b3a8-e5c97c457f07', 'es', '¿Por qué la buena energía importa más que las frases?', '["La gente recuerda las sensaciones más que el contenido", "La atracción es sobre todo visual", "Las palabras están sobrevaloradas al coquetear", "La seguridad reemplaza a la conversación"]'::jsonb, 'Lo que se queda es la experiencia emocional. Las palabras importan menos que cómo se siente el momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a3ec5acd-f47b-4bb8-bf22-81d9b16edd73', 'es', 'Un grupo relajado está conversando con calma. ¿Cómo debería mostrarse tu energía?', '["Con mucha energía para destacar", "Un poco más relajada que la de ellos", "Igual a su ritmo o un poco por encima", "Callada y reservada"]'::jsonb, 'Acompañar su tono mantiene un ambiente cómodo y compartido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50f09b6c-abae-46f2-a825-8acf3d58107e', 'es', '¿Qué genera la buena energía?', '["Hace que la gente se sienta más ligera y más viva", "Los invita a abrirse y a jugar", "Demuestra seguridad social y carisma", "Crea el ambiente que hace posible el coqueteo"]'::jsonb, 'La buena energía crea seguridad y ganas de jugar, y eso permite que el coqueteo surja de forma natural.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8695e9b-bb41-43c3-bf69-51511a2d5917', 'es', 'Te dice que le encanta el yoga y que es muy flexible. ¿Cómo puedes usar el humor?', '["Enumerar en serio los beneficios del yoga para la salud", "Contarle tu rutina de yoga en serio", "Preguntarle cuánto tiempo lleva practicando", "Preguntarle en broma si llega a tocarse los pies"]'::jsonb, 'Tomarle un poco el pelo crea una energía juguetona e invita al ida y vuelta con humor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8150d416-c806-4f77-898e-1532d0bc733f', 'es', '¿Qué deberías evitar al tomarle el pelo?', '["Exagerar algo de lo que parece estar orgullosa", "Un ida y vuelta desenfadado", "Retarla en broma sobre lo que dijo", "Temas que puedan hacerla sentir insegura"]'::jsonb, 'Tomarle el pelo funciona cuando es divertido, no cuando puede herirla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e5a0bc4-d01b-4f85-9404-749642fa56b6', 'es', '¿Cuáles son ejemplos de temas seguros para tomarle el pelo?', '["Su aspecto físico", "Que es muy competitiva", "Que es demasiado organizada", "Que cocina muy mal"]'::jsonb, 'Tómale el pelo con rasgos ligeros, que no amenacen y que no estén ligados a inseguridades.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63acae8c-e04a-4fc9-98cb-693c477cc5f0', 'es', '¿Qué hace eficaces los retos ligeros y divertidos?', '["Le dan permiso para ser competitiva y mostrar su personalidad", "Gane quien gane, hay un motivo para seguir la interacción", "Pasa de responder preguntas a jugar de verdad", "Todas las anteriores"]'::jsonb, 'Los retos ligeros invitan a jugar, muestran la personalidad y mantienen viva la interacción.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9ce27a06-8ab6-4d7f-9ede-e0cfb8108698', 'es', 'Te pregunta: “¿Cuántos años tienes?”. ¿Qué podrías decir como reto divertido?', '["Decirle tu edad exacta directamente", "Decirle que la edad no importa", "Ignorar la pregunta", "“¿Cuántos me echas? Adivina”"]'::jsonb, 'Conviértelo en un juego de adivinar para crear tensión compartida y un ida y vuelta con humor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e5d1aff-d472-4ad6-af85-3661a0c5fa0d', 'es', '¿Qué ejemplos de retos ligeros funcionan bien?', '["“A que no dices tres capitales más rápido que yo”", "“A que adivino qué sueles pedir de tomar”", "“¿Cuántos me echas? Adivina”", "“Piedra, papel o tijera por la siguiente ronda”"]'::jsonb, 'Un reto ligero es un juego compartido, no una prueba ni una presión. No hay nada real en juego.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('72b1b5eb-51d6-4bae-82e9-d9b516852a92', 'es', '¿Qué hace que la picardía funcione en vez de ofender?', '["La calidez al decirlo: la sonrisa deja claro que estás jugando", "El tono importa más que las palabras exactas", "Un enfoque ligero e inesperado, no cruel ni crítico", "Todas las anteriores"]'::jsonb, 'La picardía funciona cuando la calidez, el tono y la ligereza indican juego, no juicio.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c04e3fb3-07b8-49cb-9664-d35c6a113928', 'es', 'Te dice: “Siempre llego tarde”. ¿Qué podrías decir?', '["“Menos mal que yo soy muy paciente”", "“No pasa nada, nadie es perfecto.”", "“¿Por qué llegas tarde?”", "“Yo suelo ser puntual.”"]'::jsonb, 'Una respuesta pícara con una sonrisa la invita a seguirte el juego con ligereza.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('41b88925-4d87-4998-bcfb-64846e12bd89', 'es', '¿Por qué un poco de picardía ayuda al coquetear?', '["Rompe la dinámica de darle la razón en todo", "Muestra seguridad con calidez", "Crea tensión juguetona y ritmo", "Exige un desacuerdo serio"]'::jsonb, 'Llevarle un poco la contraria rompe la monotonía, crea tensión juguetona y mantiene viva la energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('73e2048d-c6ed-4778-ac5a-699f953efb85', 'es', '¿Qué cumplido tiene más probabilidades de crear conexión?', '["“Eres muy guapa.”", "“Tienes unos ojos increíbles.”", "“Seguro que te hacen cumplidos todo el tiempo.”", "“Me gusta cómo explicas las cosas.”"]'::jsonb, 'Los cumplidos llegan mejor cuando reflejan lo que ella elige hacer, no sus rasgos.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3cb92c32-a188-4032-9345-29df03006c3e', 'es', 'Te da un punto de vista interesante. ¿Qué es un buen cumplido?', '["“Qué forma tan original de verlo.”", "“Eres muy inteligente.”", "“No eres como las demás.”", "“Me gusta tu acento.”"]'::jsonb, 'Reconocer su perspectiva se siente cálido y sin presión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30a03b40-5f82-4a6d-9f66-d9ad8a4b99b5', 'es', '¿Qué cumplidos tienen más probabilidades de caer bien?', '["“Tienes una energía muy bonita cuando hablas de esto.”", "“Estás buenísima.”", "“Me gusta lo curiosa que eres con este tema.”", "“Estás fuera de mi alcance.”"]'::jsonb, 'Los mejores cumplidos son los que reconocen su forma de actuar, su energía o su carácter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1172a812-9aff-4cbd-a84b-c14454c9e1fa', 'es', '¿Qué hace que un cumplido sea coqueto y no solo amable?', '["Decirlo rápido y en tono casual", "Un ritmo pausado y una voz más cálida", "Sostener la mirada y dejar que llegue", "Palabras concretas sobre su aspecto"]'::jsonb, 'El tono, el momento y la presencia crean la señal romántica, no solo el contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9557570b-b2cb-4bd4-bb90-12db51a495fc', 'es', '¿Cómo puedes decir un cumplido para que genere atracción y no solo cortesía?', '["Sosteniendo la mirada con una pequeña sonrisa", "Con una voz más cálida y pausada", "Dejando una pausa después del cumplido", "Todas las anteriores"]'::jsonb, 'La intención que pones en el tono y el momento transmite deseo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5fab3d7-5d70-4bb8-82fa-cb750e038f03', 'es', 'Con las mismas palabras, ¿qué versión tiene más probabilidades de crear tensión romántica?', '["“Me gusta tu vestido”, dicho rápido al pasar", "“Me gusta tu vestido”, dicho sosteniendo la mirada y con una pausa tranquila", "“Me gusta tu vestido”, dicho desde detrás de ella"]'::jsonb, 'La calidez sumada a tu presencia hace que se sienta intencional y no algo dicho por decir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92141af3-4469-4cb2-aeca-c8b66beca062', 'es', '¿Qué permite que una sola frase lleve una interacción de lo cortés a lo coqueto?', '["Decir explícitamente tu intención romántica para que no haya ambigüedad", "Dejar ver tu interés de forma sutil, sin comprometerte del todo", "Hacer un cumplido más fuerte que antes para aumentar la atracción"]'::jsonb, 'Un giro coqueto funciona mejor cuando insinúa el interés en lugar de declararlo directamente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d81d87c2-562a-4457-9339-626b9b62911d', 'es', 'La charla fluye con facilidad y ella se inclina un poco hacia ti. ¿Qué frase sutil podría cambiar el tono?', '["“Eres interesante.”", "“Hablamos bien.”", "“Me gusta cómo se siente esta conversación contigo.”"]'::jsonb, 'Nombra con suavidad la vibra que ya existe y abre espacio para el coqueteo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('de314e72-aecd-48e2-9e7e-904002814fcb', 'es', '¿Qué frases sirven para cambiar el ambiente?', '["“Vamos a tomar un café algún día”", "“Me gusta cómo se siente esta conversación contigo.”", "“No esperaba conocer a alguien como tú hoy”", "“Deberíamos repetir esto algún día”"]'::jsonb, 'Un giro coqueto funciona mejor cuando insinúa el interés en lugar de declararlo directamente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc3c84b8-fcbd-4347-ba4e-29499525a333', 'es', '¿Por qué apartar la mirada demasiado rápido debilita la atracción?', '["Transmite nervios o inseguridad", "Parece de mala educación", "Confunde la conversación", "Le quita claridad a lo que dices"]'::jsonb, 'Apartar la mirada una y otra vez rompe la tensión y frena el avance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63f473ff-9a6a-4125-9a7b-03d7c4df9882', 'es', '¿Por qué el contacto visual puede cambiar una conversación mejor que un cumplido?', '["Se siente menos ensayado", "Se salta la lógica y actúa sobre lo que se siente", "Reduce la necesidad de palabras", "Todas las anteriores"]'::jsonb, 'El contacto visual actúa en lo emocional y lo instintivo, no en lo intelectual.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dd24452-9d73-4619-a644-95a9de2edd1d', 'es', '¿Qué momentos son los más adecuados para sostener la mirada?', '["Durante las pausas naturales", "Cuando ella habla con emoción", "Mientras la interrumpes", "Cuando la conversación se calma un momento"]'::jsonb, 'El contacto visual funciona mejor en momentos tranquilos y compartidos, no cuando interrumpes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79c89303-fe65-481b-8506-11cd45eaed32', 'es', 'La vibra es buena, pero te quedas lejos de ella. ¿Qué riesgo corres?', '["Parecer demasiado interesado", "Incomodarla", "Transmitir desinterés aunque tus palabras digan otra cosa", "Ir demasiado rápido"]'::jsonb, 'Una distancia que no encaja puede restarle fuerza a tu interés expresado con palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7200ef5-2102-4d79-abd9-e518cc3c8af8', 'es', 'Das un pequeño paso hacia ella y ella da un paso atrás discretamente. ¿Qué significa?', '["Necesita más espacio en este momento", "Quiere que insistas con seguridad", "Te está poniendo a prueba", "No le gustas para nada"]'::jsonb, 'Un paso atrás es información, no un rechazo. Dale espacio y vuelve a ajustarte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9930259-a42a-49fb-bdd4-9d319fe4fd04', 'es', '¿Qué errores generan incomodidad con la cercanía?', '["Acercarte antes de que haya complicidad", "Ignorar sus reacciones físicas", "Ajustar la distancia poco a poco", "Quedarte rígido aunque ella se incline hacia ti"]'::jsonb, 'La incomodidad viene de ignorar sus reacciones o de no responder a ellas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c56a1006-a63d-4532-801e-49829be4ccd2', 'es', '¿Qué ayuda a comunicar el efecto espejo con el cuerpo?', '["Atracción mediante la imitación", "Dominancia y control", "Seguridad social y comodidad", "Seguridad en ti mismo a través de la postura"]'::jsonb, 'Reflejar su postura transmite familiaridad y comodidad a nivel inconsciente, y eso favorece la complicidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a5612de-f9a6-4bc1-bcbb-29d29d0b1f91', 'es', 'Ella habla bajito y despacio durante la conversación. ¿Qué deberías igualar?', '["Subir el volumen para darle energía", "Seguir con tu tono fuerte de antes", "Hablar rápido para mantener el ritmo", "Bajar la voz y hablar más pausado"]'::jsonb, 'Igualar su energía y su tono crea complicidad de forma inconsciente.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dc61f4a-f296-4e9b-ae8f-01bd4a923b88', 'es', '¿Qué señales indican que quizá ella te está reflejando?', '["Adopta una postura parecida después de que cambias la tuya", "Iguala tu ritmo al hablar", "Te hace más preguntas", "Orienta su cuerpo hacia ti"]'::jsonb, 'La sintonía física y de energía suele indicar comodidad e implicación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('525d7416-b2f1-4458-807f-26c8a8bd7bc8', 'es', '¿Cuál es el propósito principal del contacto físico al coquetear?', '["Avanzar físicamente lo antes posible", "Poner a prueba sus límites", "Reforzar una conexión emocional que ya existe", "Sustituir a la conversación"]'::jsonb, 'El contacto funciona cuando acompaña una complicidad que ya existe, no cuando intenta crearla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5136a469-f474-4b76-bc20-841071ccf772', 'es', 'Ella sigue participando en la conversación, pero nunca te devuelve el contacto ni lo recibe con agrado. ¿Qué deberías hacer?', '["Aumentar el contacto para vencer su resistencia", "Preguntarle directamente por qué no responde", "Dejar el contacto físico y seguir solo con la conversación", "Terminar la interacción de inmediato"]'::jsonb, 'Si no hay reciprocidad física, el contacto todavía no es bienvenido. Ajústate sin forzar nada.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efe69dc3-5d6a-4f17-b046-2263cec2230f', 'es', '¿En qué momentos es apropiado introducir un contacto ligero?', '["Cuando ella se inclina hacia ti o se queda cerca", "Cuando te da respuestas cortas y corteses", "Al moverse juntos por un lugar"]'::jsonb, 'El contacto debe ir con su apertura y con el ritmo compartido, no con la neutralidad ni el desinterés.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('249a63f3-79dc-45b1-b433-50465a7a107d', 'es', '¿Por qué no impresionarte de inmediato invierte la dinámica habitual al coquetear?', '["Muestra que no la estás persiguiendo ni te estás implicando de más", "Indica que tienes tus propios criterios", "Crea equilibrio en lugar de una persecución de un solo lado", "Todas las anteriores"]'::jsonb, 'No impresionarte de inmediato hace que ella pase de esperar tu aprobación a una elección mutua.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95ad96b3-d2ef-411c-b521-ec1a1bc7d496', 'es', 'Menciona lo a menudo que la reconocen por Instagram. ¿Qué respuesta mantiene tu actitud?', '["“Qué increíble, debes de ser muy popular.”", "“¿Entonces te pido un autógrafo?”", "“¿Cuántos seguidores tienes?”", "“Te mereces toda esa atención.”"]'::jsonb, 'Llevarle un poco la contraria muestra que no te impresionas automáticamente, y eso invierte la dinámica.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7440e677-e76b-4b16-a0f9-213ae82c821a', 'es', '¿Qué frases son ejemplos sanos de no impresionarte de inmediato?', '["“Me vas a tener que convencer.”", "“Eso no es impresionante.”", "“No sé, a mí no se me conquista tan fácil.”", "“No eres tan especial.”"]'::jsonb, 'No impresionarte de inmediato debe ser un reto ligero, nunca un desprecio ni una humillación.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a91f07b0-5946-49ce-804d-b862552b9592', 'es', '¿Qué ayuda a crear tensión sexual en una interacción?', '["Temas profundos", "Una amabilidad clara y previsible", "Tranquilizarla todo el tiempo", "Cierta ambigüedad sobre tus intenciones"]'::jsonb, 'La tensión nace de la posibilidad. Cuando la intención se insinúa en lugar de declararse, la atención se agudiza.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('93982613-1848-48bb-b22b-59bd8c12b62f', 'es', '¿Qué ayuda a crear tensión sexual?', '["Sostener la mirada un instante más de lo cómodo", "Dejar que un contacto en su brazo dure un momento, si ella claramente lo está disfrutando", "Ponerte un poco más cerca, siempre que ella siga relajada", "Todas las anteriores"]'::jsonb, 'La tensión crece con pequeños momentos intencionales de cercanía y pausa.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67379ba9-deb9-45a2-b30c-f9b26b01536d', 'es', '¿Qué frases tienen más probabilidades de crear tensión?', '["“Qué buena opinión.”", "“Intento no quedarme mirándote, pero me lo pones difícil.”", "“Hay una chispa cuando hablas de lo que te gusta.”", "“¿Por qué elegiste esa bebida?”"]'::jsonb, 'Admitir en broma que te afecta, o señalar una chispa, insinúa atracción sin ser demasiado directo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43a061f7-1ccd-4592-8e5d-035717e37189', 'es', '¿Cuál es el propósito principal de retomar un detalle o de un chiste privado en la conversación?', '["Demostrar inteligencia y memoria", "Reactivar una conversación estancada", "Crear continuidad y una conexión compartida", "Repetir algo que ella dijo para aclararlo"]'::jsonb, 'Crean una sensación de historia compartida, y eso hace que pasen de desconocidos a cómplices.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('344744cd-ace9-45d2-96db-317d056f2f2f', 'es', '¿Qué hace eficaz retomar un detalle?', '["Construir sobre ese detalle con humor o un giro juguetón", "Crear continuidad en lugar de temas desconectados", "Hacer que la conversación se sienta como algo que crece, no algo que simplemente pasa", "Todas las anteriores"]'::jsonb, 'Que te recuerden hace que te sientas visto, y eso aumenta la comodidad y la conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a584c7b-29ae-4ef4-8faf-ee465bb72e66', 'es', '¿Qué momentos sirven para retomar después o para un chiste privado?', '["Pequeñas bromas que ella hizo", "Gustos o manías pequeñas que mencionó", "Problemas personales", "Opiniones ligeras o exageraciones"]'::jsonb, 'Retomar funciona mejor con detalles ligeros, juguetones o que dicen algo de quién es.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0395cf63-6575-4c9c-aaa2-83805005ade7', 'es', 'Te dice que es muy buena adivinando el signo zodiacal de la gente. ¿Cómo puedes crear un reto divertido?', '["Decirle tu signo directamente", "Decirle que la astrología no es real", "Preguntarle en serio por qué cree en eso", "“A ver, adivina el mío.”"]'::jsonb, 'Invítala a adivinar, como un juego, para despertar tensión compartida y un ida y vuelta con humor.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('061b4ffe-6aea-49da-b29e-1976fc8c62a3', 'es', '“¿Qué vas a pedir?” frente a “A que adivino lo que vas a pedir”. ¿Cuál crea más química?', '["La primera: muestra un interés genuino por sus gustos", "La segunda: el reto juguetón genera participación y diversión", "La primera: es mejor para crear complicidad", "La segunda: demuestra seguridad"]'::jsonb, 'Un juego de adivinar es un reto juguetón que exige su participación y genera energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0640bea3-7134-4d3d-bbd1-a2dd404d8c97', 'es', 'Se acerca un poco más mientras se ríe. ¿Cuál es la mejor respuesta?', '["Quedarte congelado para no malinterpretarlo", "Dar un paso atrás para ir a lo seguro", "Igualar su cercanía con calma", "Cambiar de tema"]'::jsonb, 'Acompañar su movimiento mantiene la interacción en sintonía y cómoda.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dcb3ce2-da4e-48c3-8c5b-7ded4177d531', 'es', 'Ella te toma el pelo a ti por lo mal que cocinas. ¿Qué podrías hacer?', '["Ponerte a la defensiva y dar explicaciones", "Cambiar de tema rápido", "Reírte y seguirle la broma", "Tomarle el pelo a ella más en serio"]'::jsonb, 'Devolver el juego muestra seguridad y crea química.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f0fa46d-8699-4a6c-9b7b-2fe8afa91fe5', 'es', 'Te describe con entusiasmo un pasatiempo poco común. ¿Qué cumplido es mejor?', '["“Eres única.”", "“Me gusta lo apasionada que eres con eso, se te nota mucho.”", "“Tienes intereses muy buenos.”", "“Te ves atractiva cuando te emocionas.”"]'::jsonb, 'Es concreto sobre cómo expresa lo que eligió y muestra que valoras su energía.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14f120e4-9b66-4b46-81d5-b125235fb2f5', 'es', '¿En qué se diferencia la tensión sexual de una conversación amistosa?', '["Depende de temas serios y de compartir a fondo", "Evita cualquier señal no verbal o pausa", "Introduce una incertidumbre sutil sobre las intenciones", "Mantiene la dinámica totalmente previsible"]'::jsonb, 'La chispa nace de insinuar algo más sin dejarlo del todo claro.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17429248-a6f9-42cf-a924-9553dec0b010', 'es', '¿Qué elementos hacen que las mismas palabras pasen de amables a coquetas?', '["Decirlas más despacio y con la voz suave", "Un ritmo rápido y la mirada apartada", "Sostener la mirada con una sonrisa", "Dejar que el momento respire después"]'::jsonb, 'La presencia y el momento le dan chispa sin cambiar el contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1bcaa8b7-9201-4ec7-bab9-cd622fb9b421', 'es', '¿Qué frases tienen más probabilidades de crear tensión?', '["“Tienes una presencia muy tranquila, me gusta”", "“Qué interesante, cuéntame más.”", "“¿Y a qué te dedicas?”", "“Me gusta cómo sostienes la mirada.”"]'::jsonb, 'Los comentarios sobre su presencia o sobre la atracción indican tu intención sin forzarla.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e531297-8fe5-432d-9e8a-8bb1970f99ba', 'es', '¿Por qué sostener la mirada tiene tanto poder a nivel fisiológico?', '["Demuestra dominancia social de forma natural", "Libera oxitocina, acelera el pulso y genera sensación de intimidad", "Crea una vulnerabilidad que construye conexión emocional"]'::jsonb, 'El cuerpo responde primero al contacto visual; aumenta de forma natural las señales de intimidad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e723f5c-f299-44f4-844c-f7190b8f4c42', 'es', 'La charla va bien y ella sostiene la mirada más de lo normal. ¿Qué deberías hacer?', '["Apartar la mirada para hacer una pregunta", "Sostenerla también con una pequeña sonrisa y dejar que el momento se alargue", "Bajar la vista para darle espacio", "Exagerar la mirada para avanzar rápido"]'::jsonb, 'Responder a una mirada sostenida crea intimidad sin palabras.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bcd40a3-8939-4555-8f99-7c394079b7a0', 'es', '¿Por qué los cumplidos concretos sobre lo que ella elige crean más conexión?', '["Se sienten como un reconocimiento genuino de su esfuerzo", "Muestran que te fijaste en algo que depende de ella", "Evalúan directamente su aspecto"]'::jsonb, 'Hacen que se sienta vista por quién es, no por lo que heredó.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d067124-8ee8-41b8-b580-f480159f861e', 'es', 'Ella te mira directamente durante una pausa en la conversación. ¿Qué deberías hacer?', '["Apartar rápido la mirada para evitar un momento incómodo", "Mirarla fijamente sin sonreír", "Bajar la vista y seguir hablando", "Sonreír con suavidad y sostener su mirada con calma"]'::jsonb, 'Te está dando la oportunidad de sostener la mirada. Sostenla también; no la rompas por nervios.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fc0d39c-22da-4308-8ee9-4ab4c88299d2', 'es', '¿Qué creencia favorece más un coqueteo respetuoso?', '["“Si no insisto, me pierdo oportunidades”", "“El rechazo significa que hice algo mal”", "“Tener seguridad es no echarse nunca para atrás”", "“No todas las interacciones tienen que continuar”"]'::jsonb, 'El respeto empieza por aceptar que el desinterés es normal y no un fracaso personal.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('34e3a8a0-43de-4673-af81-d73381d0ceba', 'es', 'Te dice que es muy buena adivinando de qué país es la gente. ¿Qué podrías hacer para crear un reto divertido?', '["Decirle de dónde eres directamente", "Elogiar su habilidad", "Preguntarle en serio por sus viajes", "“Demuéstralo: adivina de dónde soy.”"]'::jsonb, 'Invítala a adivinar, como un juego, para que participen los dos y se tomen el pelo.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36c3a4cc-1b9f-42ea-a62f-551942c80f5d', 'es', '¿Qué hace eficaz un reto ligero al coquetear?', '["Que no haya nada importante en juego y dé pie a bromear", "Que haya mucho en juego para demostrar lo que vales", "Poner a prueba en serio lo que sabe", "Que uno de los dos gane claramente"]'::jsonb, 'Que no haya nada en juego lo mantiene divertido, y gane quien gane alimenta la conexión.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37dce606-feeb-4072-baf2-17e1f94a6f8e', 'es', 'Hace un comentario ingenioso sobre la gente de la cafetería. ¿Qué podrías decir?', '["“Tienes unos ojos muy bonitos.”", "“Te ves muy bien hoy.”", "“Eres graciosa.”", "“Qué forma tan original de decirlo. No me había fijado.”"]'::jsonb, 'Se relaciona directamente con su punto de vista y la hace sentirse vista de verdad.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('384c4054-61db-4bdb-b2c8-91998d08cbee', 'es', '¿Qué efectos puede tener sostener la mirada?', '["Mayor sensación de intimidad", "Excitación fisiológica", "Comunicar con claridad tu interés", "Presión social para responder con palabras"]'::jsonb, 'El contacto visual comunica interés sin palabras y sin obligar a responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d71381-3505-4e35-9880-fe45c1d756bb', 'es', '¿Por qué retomar detalles o tener chistes privados refuerza la conexión?', '["Crean un hilo privado entre los dos", "Muestran que de verdad estabas escuchando", "Crean referencias compartidas y familiaridad", "Todas las anteriores"]'::jsonb, 'Retomar detalles convierte rápido a dos desconocidos en personas con una historia compartida.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3adb725c-dd19-430c-9522-0dfd8285559a', 'es', 'Te dice que cocina muy mal. ¿Qué respuestas son juguetonas?', '["“¿Entonces cenas cereal?”", "“No pasa nada, la cocina no es para todo el mundo”", "“Qué pena, yo cocino mucho”", "“¿Tan mal? ¿Se te quema hasta el agua?”"]'::jsonb, 'Tomarle el pelo funciona cuando mantiene todo ligero y la invita a responder.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3cfd9dfa-fc1f-49af-862d-aea72f90adc9', 'es', 'Maneja un momento incómodo con elegancia y humor. ¿Qué podrías decir?', '["“Qué bien manejaste eso.”", "“Eres perfecta.”", "“Tienes una sonrisa preciosa.”", "“Eso no fue nada.”"]'::jsonb, 'Reconoce su habilidad social y cómo eligió actuar en ese momento.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('405b2702-ed84-4c3b-9a21-77729ea9f2d4', 'es', 'Mira la carta y dice: “Le doy demasiadas vueltas a todo”. ¿Cuál es la mejor respuesta pícara?', '["“Eso es bastante común.”", "“¿Entre qué estás dudando?”", "“Ya lo vas a resolver.”", "“Se nota. Es claramente una decisión de vida o muerte.”"]'::jsonb, 'Exagerar con calidez crea humor y ritmo sin intentar impresionar.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('44e9bef3-c0f2-4d31-a3a2-481c50c7d9d5', 'es', '¿Qué frases tienen más probabilidades de crear tensión?', '["“Qué historia tan graciosa.”", "“Cuéntame más de tu trabajo.”", "“Hay algo en tu forma de sonreír…”", "“Tienes una energía muy cálida.”"]'::jsonb, 'Los comentarios suaves sobre su sonrisa o su energía insinúan atracción y crean una chispa sutil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450fc086-463d-40c5-9ce4-77e9a664a8e7', 'es', 'Te dice: “Este café está carísimo”. ¿Qué podrías decir?', '["“Sí, los precios están por las nubes en todos lados.”", "“Deberías hacerlo en casa.”", "“Pero tú claramente mereces la mezcla premium.”", "“¿Cuánto te costó el tuyo?”"]'::jsonb, 'Un cumplido pícaro envuelto en una broma despierta una energía coqueta.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4684c791-9598-4381-9511-739d9afdfead', 'es', '¿Qué reacciones indican que tu humor funcionó?', '["Se ríe de verdad", "Te corrige en broma", "Te devuelve las bromas", "Te da respuestas cortas y corteses"]'::jsonb, 'La participación y la reciprocidad son luz verde. Las respuestas cortas y corteses, no.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4962a3a5-8566-4b58-aafd-36f4a302ce53', 'es', '¿Por qué quedarte demasiado lejos durante toda la interacción puede debilitar la atracción?', '["Puede transmitir falta de interés o inseguridad", "Se siente de mala educación", "La confunde", "Hace más lento el ritmo de la conversación"]'::jsonb, 'Tus palabras pueden mostrar interés, pero la distancia transmite duda.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49634200-5e42-4c7d-b10f-352eb5b017a0', 'es', '¿Por qué al empezar a coquetear la energía importa más que las palabras?', '["Crea el tono emocional al que la gente responde primero", "Una energía cálida y alegre hace que los demás se sientan más ligeros", "La energía baja siempre transmite seguridad"]'::jsonb, 'La gente se acerca a las sensaciones positivas y estimulantes antes que al contenido.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
